const item = $input.item.json;
const body = item.body || item;
const email = (body.email || '').trim().toLowerCase();
const name = (body.name || 'Anonymous').trim();
const company = (body.company || '').trim();
const message = (body.message || body.notes || '').trim();
const budget = body.budget ? String(body.budget).trim() : '';

if (!email || !email.includes('@')) {
  throw new Error('Missing or invalid email address.');
}

return {
  json: {
    leadId: 'lead_' + Date.now().toString(36) + Math.random().toString(36).substr(2, 5),
    timestamp: new Date().toISOString(),
    name,
    email,
    company,
    budget,
    message
  }
};

const lead = $input.item.json;
const parts = lead.email.split('@');
const domain = parts[1] || '';
const freeProviders = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', '163.com', 'qq.com'];
const isCorporate = !freeProviders.includes(domain) && domain.includes('.');

return {
  json: {
    ...lead,
    domain,
    isCorporateDomain: isCorporate
  }
};

const lead = $input.item.json;
let score = 20; // baseline for valid submission
const breakdown = [];

// 1. Corporate Domain signal (+30)
if (lead.isCorporateDomain) {
  score += 30;
  breakdown.push('corporate_domain (+30)');
}

// 2. Budget signals (+25)
const budgetStr = lead.budget.toLowerCase();
if (budgetStr.includes('k') || budgetStr.includes('000') || budgetStr.includes('enterprise') || /\$[1-9]/.test(budgetStr)) {
  score += 25;
  breakdown.push('high_budget_stated (+25)');
} else if (lead.budget) {
  score += 15;
  breakdown.push('budget_stated (+15)');
}

// 3. Message depth & buying urgency (+25)
const msg = lead.message.toLowerCase();
const highIntentKeywords = ['demo', 'pricing', 'hire', 'contract', 'urgent', 'timeline', 'decision', 'team', 'integrate', 'migration'];
let keywordHits = 0;
highIntentKeywords.forEach(k => {
  if (msg.includes(k)) keywordHits++;
});

if (keywordHits >= 2 || msg.length > 180) {
  score += 25;
  breakdown.push('high_intent_message (+25)');
} else if (keywordHits === 1 || msg.length > 50) {
  score += 15;
  breakdown.push('moderate_intent_message (+15)');
}

score = Math.min(100, Math.max(0, score));
const tier = score >= 70 ? 'HOT' : (score >= 45 ? 'WARM' : 'NURTURE');

return {
  json: {
    ...lead,
    qualificationScore: score,
    qualificationTier: tier,
    scoreBreakdown: breakdown
  }
};

const lead = $input.item.json;
const text = `🔥 *HOT LEAD ALERT* (${lead.qualificationScore}/100)\n*Name:* ${lead.name} (${lead.email})\n*Company:* ${lead.company || lead.domain}\n*Budget:* ${lead.budget || 'Not specified'}\n*Message:* "${lead.message}"\n*Signals:* ${lead.scoreBreakdown.join(', ')}`;

return {
  json: {
    ...lead,
    slackPayload: {
      text: `🔥 Hot Lead: ${lead.name} (${lead.qualificationScore}/100)`,
      attachments: [{
        color: '#ff334b',
        text: text,
        footer: `AutomateStack Intake • ID: ${lead.leadId}`
      }]
    }
  }
};

const lead = $input.item.json;
const text = `📋 *New Lead Submitted* (${lead.qualificationScore}/100 - ${lead.qualificationTier})\n*Name:* ${lead.name} (${lead.email})\n*Company:* ${lead.company || lead.domain}\n*Budget:* ${lead.budget || 'N/A'}\n*Message:* "${lead.message}"`;

return {
  json: {
    ...lead,
    slackPayload: {
      text: `New Lead: ${lead.name} (${lead.qualificationScore}/100)`,
      attachments: [{
        color: '#2ea44f',
        text: text,
        footer: `AutomateStack Intake • ID: ${lead.leadId}`
      }]
    }
  }
};
